import { reactive, ref } from 'vue';
import { getContext } from '@/st/context';
import type { NotesSettings } from './types';
export const NOTES_SETTINGS_KEY = 'prism_book_notes_settings';
export const settingsIssue = ref('');
/** 札记的默认最大输出。思考型模型的思考也算在里面，3000 经常不够。 */
export const NOTES_DEFAULT_MAX_TOKENS = 8000;
export const NOTES_MAX_TOKENS_LIMIT = 65535;
/** 旧版保存设置时没有记下默认值，那时的默认是 3000。 */
const LEGACY_DEFAULT_MAX_TOKENS = 3000;
const defaults = (): NotesSettings => ({ enabled: false, autoGenerate: false, injectConfirmed: false, recentFloors: 8, memoryChars: 12000,
  channel: { id: 'prism-notes-independent', name: '双子札记独立 API', url: '', key: '', model: '', temperature: 0.8, maxTokens: NOTES_DEFAULT_MAX_TOKENS, timeoutSec: 180, stream: true, prefill: false, excludeParams: [], reasoningEffort: '' } });
export const notesSettings = reactive<NotesSettings>(defaults());
let protectedSettings = false;
const bounded = (v: unknown, fallback: number, lo: number, hi: number) => typeof v === 'number' && Number.isFinite(v) ? Math.max(lo, Math.min(hi, v)) : fallback;
function normalize(value: Partial<NotesSettings>): NotesSettings {
  const d = defaults(), c = value.channel ?? d.channel;
  return { enabled: value.enabled === true, autoGenerate: value.autoGenerate === true, injectConfirmed: value.injectConfirmed === true,
    recentFloors: Math.floor(bounded(value.recentFloors,8,1,40)), memoryChars: Math.floor(bounded(value.memoryChars,12000,1000,40000)),
    channel: { ...d.channel, url: typeof c.url === 'string' ? c.url.trim() : '', key: typeof c.key === 'string' ? c.key : '', model: typeof c.model === 'string' ? c.model.trim() : '',
      temperature: bounded(c.temperature,.8,0,2), maxTokens: Math.floor(bounded(c.maxTokens,NOTES_DEFAULT_MAX_TOKENS,256,NOTES_MAX_TOKENS_LIMIT)), timeoutSec: Math.floor(bounded(c.timeoutSec,180,10,600)), stream: c.stream !== false } };
}
export function hydrateNotesSettings(): void {
  settingsIssue.value = ''; protectedSettings = false; Object.assign(notesSettings, defaults());
  const raw = getContext()?.extensionSettings?.[NOTES_SETTINGS_KEY];
  if (raw == null) return;
  if (typeof raw !== 'object' || Array.isArray(raw) || (raw as any).version !== 1 || typeof (raw as any).channel !== 'object' || !(raw as any).channel) {
    protectedSettings = true; settingsIssue.value = '札记设置的格式认不出来，已经只读保护，原设置没有被覆盖。'; return;
  }
  const next = normalize(raw);
  // 保存时就是当时的默认值，说明用户没改过：跟着用现在的默认（与时间标签提示词的升级做法一致）。改过的值原样保留。
  const savedDefault = typeof (raw as any).defaultMaxTokens === 'number' ? (raw as any).defaultMaxTokens : LEGACY_DEFAULT_MAX_TOKENS;
  if ((raw as any).channel.maxTokens === savedDefault) next.channel.maxTokens = NOTES_DEFAULT_MAX_TOKENS;
  Object.assign(notesSettings, next);
}
export function saveNotesSettings(): void {
  if (protectedSettings) throw new Error(settingsIssue.value);
  const ctx = getContext();
  if (!ctx?.extensionSettings || !ctx.saveSettingsDebounced) throw new Error('酒馆设置接口还没就绪，设置没有保存。');
  Object.assign(notesSettings, normalize(notesSettings));
  const previous = ctx.extensionSettings[NOTES_SETTINGS_KEY];
  if (previous != null && (typeof previous !== 'object' || (previous as any).version !== 1)) throw new Error('札记设置的版本已变化，没有覆盖；请刷新页面后检查。');
  ctx.extensionSettings[NOTES_SETTINGS_KEY] = { version: 1, defaultMaxTokens: NOTES_DEFAULT_MAX_TOKENS, ...JSON.parse(JSON.stringify(notesSettings)) };
  try { ctx.saveSettingsDebounced(); settingsIssue.value = ''; }
  catch { if (previous === undefined) delete ctx.extensionSettings[NOTES_SETTINGS_KEY]; else ctx.extensionSettings[NOTES_SETTINGS_KEY] = previous; settingsIssue.value = '札记设置保存失败，请稍后再试。'; throw new Error(settingsIssue.value); }
}
export function validateNotesChannel(): void {
  if (protectedSettings) throw new Error(settingsIssue.value);
  const c = notesSettings.channel;
  if (!c.url.trim() || !c.model.trim()) throw new Error('请先在「札记 → 独立 API 设置」里填写地址和模型名（札记不会借用正文或摘要的 API）。');
  let url: URL; try { url = new URL(c.url); } catch { throw new Error('札记的 API 地址不是有效的网址。'); }
  if (!['https:', 'http:'].includes(url.protocol) || url.username || url.password || url.search || url.hash) throw new Error('札记的 API 地址要写完整的 http(s) 地址，不能带账号、? 参数或 #。');
}
